#include <iostream>
#include <cmath>

bool calcular_lado(double area, double& destino) {
    if (!std::isfinite(area) || area < 0.0 || area > 100.0) {
        return false;
    }
    const double lado = std::sqrt(area);
    destino = lado;
    return true;
}

int main() {
    double area{36.0};
    double destino{-3.0};
    const bool valida = calcular_lado(area, destino);
    std::cout << "Valide : " << valida << ";Destination : " << destino
              << ";Aire : " << area << "\n";
    area = -2.0;
    const bool negativa = calcular_lado(area, destino);
    std::cout << "Négative : " << negativa << ";Destination : " << destino
              << ";Aire : " << area << "\n";
    area = 100.5;
    const bool exceso = calcular_lado(area, destino);
    std::cout << "Excès : " << exceso << ";Destination : " << destino
              << ";Aire : " << area << "\n";
    area = 0.0;
    const bool cero = calcular_lado(area, destino);
    std::cout << "Zéro : " << cero << ";Destination : " << destino
              << ";Aire : " << area << "\n";
    return 0;
}

